gFO(){return"\u062a\u062d\u062f\u064a\u062f \u0648\u0642\u062a \u0627\u0644\u0641\u062c\u0631 \u0648\u0627\u0644\u0639\u0634\u0627\u0621 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u0644\u064a\u0644."},
gFQ(){return"\u0627\u0633\u062a\u062e\u062f\u0645 \u0633\u0628\u0639 \u0627\u0644\u0644\u064a\u0644."},
gFM(){return"\u0627\u0633\u062a\u062e\u062f\u0645 \u0632\u0627\u0648\u064a\u062a\u064a \u0627\u0644\u0641\u062c\u0631 \u0648\u0627\u0644\u0639\u0634\u0627\u0621 \u0643\u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u0644\u064a\u0644."},
gKZ(){return"12 \u0633\u0627\u0639\u0629"},
gL_(){return"24 \u0633\u0627\u0639\u0629"},
gHX(){return"\u0625\u0630\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0645\u062a\u0648\u0642\u0641. \u0644\u0645 \u064a\u062a\u0645 \u062a\u0641\u0639\u064a\u0644 \u062a\u0630\u0643\u064a\u0631\u0627\u062a \u0627\u0644\u0635\u0644\u0627\u0629."},
gHY(){return"\u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0644\u0629 \u0637\u0644\u0628 \u0625\u0630\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a."},
gvY(){return"\u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0644\u0629 \u0637\u0644\u0628 \u0625\u0630\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a. \u062d\u0627\u0648\u0644 \u0625\u0639\u0627\u062f\u0629 \u0641\u062a\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0641\u064a \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0646\u0638\u0627\u0645."},
gHU(){return"\u062a\u0639\u0630\u0631 \u0637\u0644\u0628 \u0625\u0630\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a."},
gvV(){return"\u062a\u0639\u0630\u0631 \u0637\u0644\u0628 \u0625\u0630\u0646 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a. \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0623\u0648 \u0642\u0645 \u0628\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0641\u064a \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0646\u0638\u0627\u0645."},
gIn(){return"\u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0644\u0629 \u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a. \u0627\u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u064a \u0623\u0646\u062f\u0631\u0648\u064a\u062f \u064a\u062f\u0648\u064a\u064b\u0627 \u0648\u0642\u0645 \u0628\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a."},
gIm(){return"\u062a\u0639\u0630\u0631 \u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a. \u0627\u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0641\u064a \u0623\u0646\u062f\u0631\u0648\u064a\u062f \u064a\u062f\u0648\u064a\u064b\u0627 \u0648\u0642\u0645 \u0628\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a."},
gIl(){return"\u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0644\u0629 \u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0625\u0630\u0646 \u0627\u0644\u0645\u0646\u0628\u0647. \u0627\u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u0646\u0628\u0647\u0627\u062a \u0648\u0627\u0644\u062a\u0630\u0643\u064a\u0631\u0627\u062a \u0641\u064a \u0623\u0646\u062f\u0631\u0648\u064a\u062f \u064a\u062f\u0648\u064a\u064b\u0627 \u0648\u0642\u0645 \u0628\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0646\u0628\u0647\u0627\u062a \u0627\u0644\u062f\u0642\u064a\u0642\u0629."},
gIk(){return"\u062a\u0639\u0630\u0631 \u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0625\u0630\u0646 \u0627\u0644\u0645\u0646\u0628\u0647. \u0627\u0641\u062a\u062d \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u0646\u0628\u0647\u0627\u062a \u0648\u0627\u0644\u062a\u0630\u0643\u064a\u0631\u0627\u062a \u0641\u064a \u0623\u0646\u062f\u0631\u0648\u064a\u062f \u064a\u062f\u0648\u064a\u064b\u0627 \u0648\u0642\u0645 \u0628\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0646\u0628\u0647\u0627\u062a \u0627\u0644\u062f\u0642\u064a\u0642\u0629."},
