gAn(){return"\u062f\u0631 \u0635\u0648\u0631\u062a \u0648\u062c\u0648\u062f\u060c \u0631\u0648\u0634\u06cc \u0627\u0632 \u06a9\u0634\u0648\u0631 \u0630\u062e\u06cc\u0631\u0647 \u0634\u062f\u0647 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
gFN(){return"\u06cc\u06a9 \u0642\u0627\u0646\u0648\u0646 \u0631\u0627 \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0645\u06a9\u0627\u0646\u200c\u0647\u0627\u06cc \u062f\u0627\u0631\u0627\u06cc \u0639\u0631\u0636 \u062c\u063a\u0631\u0627\u0641\u06cc\u0627\u06cc\u06cc \u0628\u0627\u0644\u0627 \u0627\u0639\u0645\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gFP(){return"\u0642\u0627\u0646\u0648\u0646 \u0639\u0631\u0636 \u062c\u063a\u0631\u0627\u0641\u06cc\u0627\u06cc\u06cc \u0628\u0627\u0644\u0627 \u0627\u0639\u0645\u0627\u0644 \u0646\u0634\u0648\u062f."},
gFO(){return"\u0645\u062d\u0627\u0633\u0628\u0647 \u0635\u0628\u062d \u0648 \u0639\u0634\u0627\u0621 \u0631\u0627 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0646\u06cc\u0645\u0647\u200c\u0634\u0628 \u0645\u062d\u062f\u0648\u062f \u06a9\u0646\u06cc\u062f."},
gFQ(){return"\u0627\u0632 \u06cc\u06a9\u200c\u0647\u0641\u062a\u0645 \u0634\u0628 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."},
gFM(){return"\u0627\u0632 \u0632\u0648\u0627\u06cc\u0627\u06cc \u0635\u0628\u062d \u0648 \u0639\u0634\u0627\u0621 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06a9\u0633\u0631 \u0634\u0628 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."},
