gL_(){return"\u06f2\u06f4 \u0633\u0627\u0639\u062a\u0647"},
gHX(){return"\u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a. \u06cc\u0627\u062f\u0622\u0648\u0631\u0647\u0627\u06cc \u0646\u0645\u0627\u0632 \u0641\u0639\u0627\u0644 \u0646\u0634\u062f\u0646\u062f."},
gHY(){return"\u0645\u062f\u062a \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0627\u0639\u0644\u0627\u0646 \u0628\u0647 \u067e\u0627\u06cc\u0627\u0646 \u0631\u0633\u06cc\u062f."},
gvY(){return"\u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0627\u0639\u0644\u0627\u0646 \u0628\u0627 \u062a\u0623\u062e\u06cc\u0631 \u0645\u0648\u0627\u062c\u0647 \u0634\u062f. \u0644\u0637\u0641\u0627\u064b \u062f\u0648\u0628\u0627\u0631\u0647 \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627 \u0628\u0627\u0632 \u06a9\u0646\u06cc\u062f \u06cc\u0627 \u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627 \u0631\u0627 \u0627\u0632 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0633\u06cc\u0633\u062a\u0645 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gHU(){return"\u0627\u0645\u06a9\u0627\u0646 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0627\u0639\u0644\u0627\u0646 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0634\u062a."},
gvV(){return"\u0627\u0645\u06a9\u0627\u0646 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u0647 \u0627\u0639\u0644\u0627\u0646 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0634\u062a. \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f \u06cc\u0627 \u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627 \u0631\u0627 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0633\u06cc\u0633\u062a\u0645 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gIn(){return"\u0632\u0645\u0627\u0646 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0627\u0639\u0644\u0627\u0646 \u0628\u0647 \u067e\u0627\u06cc\u0627\u0646 \u0631\u0633\u06cc\u062f. \u0644\u0637\u0641\u0627\u064b \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0628\u0631\u0646\u0627\u0645\u0647 \u0627\u0646\u062f\u0631\u0648\u06cc\u062f \u0631\u0627 \u0628\u0647 \u0635\u0648\u0631\u062a \u062f\u0633\u062a\u06cc \u0628\u0627\u0632 \u06a9\u0631\u062f\u0647 \u0648 \u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gIm(){return"\u0627\u0645\u06a9\u0627\u0646 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0627\u0639\u0644\u0627\u0646 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0634\u062a. \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0628\u0631\u0646\u0627\u0645\u0647 \u0627\u0646\u062f\u0631\u0648\u06cc\u062f \u0631\u0627 \u0628\u0647 \u0635\u0648\u0631\u062a \u062f\u0633\u062a\u06cc \u0628\u0627\u0632 \u06a9\u0631\u062f\u0647 \u0648 \u0627\u0639\u0644\u0627\u0646\u200c\u0647\u0627 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gIl(){return"\u0632\u0645\u0627\u0646 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0647\u0634\u062f\u0627\u0631 \u0628\u0647 \u067e\u0627\u06cc\u0627\u0646 \u0631\u0633\u06cc\u062f. \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0647\u0634\u062f\u0627\u0631\u0647\u0627\u06cc \u0627\u0646\u062f\u0631\u0648\u06cc\u062f \u0631\u0627 \u062f\u0633\u062a\u06cc \u0628\u0627\u0632 \u06a9\u0631\u062f\u0647 \u0648 \u0647\u0634\u062f\u0627\u0631\u0647\u0627\u06cc \u062f\u0642\u06cc\u0642 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gIk(){return"\u0627\u0645\u06a9\u0627\u0646 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u062f\u0633\u062a\u0631\u0633\u06cc \u0647\u0634\u062f\u0627\u0631 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0634\u062a. \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0647\u0634\u062f\u0627\u0631\u0647\u0627\u06cc \u0627\u0646\u062f\u0631\u0648\u06cc\u062f \u0631\u0627 \u062f\u0633\u062a\u06cc \u0628\u0627\u0632 \u06a9\u0631\u062f\u0647 \u0648 \u0647\u0634\u062f\u0627\u0631\u0647\u0627\u06cc \u062f\u0642\u06cc\u0642 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gC3(){return"\u062f\u0631\u062c\u0647"},
gvQ(){return"\u062f\u0642\u06cc\u0642\u0647"},
IQ(a){return"\u0627\u062e\u062a\u0644\u0627\u0641 \u0632\u0645\u0627\u0646 "+a},
gyl(){return"\u062f\u0642\u0627\u06cc\u0642 \u0631\u0627 \u0641\u0642\u0637 \u0628\u0647 \u0635\u0648\u0631\u062a \u0639\u062f\u062f \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f. \u0627\u0632 \u062f\u06a9\u0645\u0647 \u0639\u0644\u0627\u0645\u062a \u0628\u0631\u0627\u06cc \u0642\u0628\u0644 \u06cc\u0627 \u0628\u0639\u062f \u0627\u0632 \u0632\u0645\u0627\u0646 \u0645\u062d\u0627\u0633\u0628\u0647 \u0634\u062f\u0647 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f."},
